import argparse
from collections import Counter, defaultdict
import datetime
import json
from pathlib import Path


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--results', action='append', default=[])
    parser.add_argument('--combined')
    args = parser.parse_args()
    data = json.loads(Path('lab/test-selection.json').read_text())
    measurements = {}
    runs = []
    for source in args.results:
        report = json.loads(Path(source).read_text())
        runs.append((Path(source).name, report))
        for row in report['results']:
            if 'serial' not in Path(source).name or row['id'] not in measurements:
                measurements[row['id']] = row
    entries = data['scenarios']
    counts = Counter(e['recommendation'] for e in entries)
    real_sets = defaultdict(list)
    for e in entries:
        if 'real' in e['levels']:
            real_sets[e['feature'].split('.')[0]].append(e['id'])
    proposed = ['HELPER-TCC-READY', 'MSG-INCOMING', 'REM-CRUD', 'CAL-CRUD', 'CON-CRUD', 'NOTE-CRUD', 'USE-IMPORT', 'SAF-HISTORY-REAL', 'CALL-READ-REAL', 'VM-CAPTURE', 'VMEMO-CAPTURE', 'MAIL-READ-REAL', 'MAIL-SEND-SELF-REAL', 'FILE-CRUD-REAL', 'MAC-POWER-REAL', 'CAP-SIM', 'BT-REAL', 'FOC-STATUS-REAL', 'SC-RUN-REAL', 'CLK-TIMER-REAL', 'MAP-SEARCH-REAL', 'AUD-TRANSCRIBE', 'VIS-OCR', 'PDF-TEXT', 'MSG-SELFTEST', 'MSG-READSTATE-REAL', 'MSG-DELETE-REAL']
    smoke = [s for s in proposed if any(e['id'] == s and 'real' in e['levels'] for e in entries)]
    lines = ['# Test inventory and migration selection proposal', '', 'Baseline measurements: main `10a397d6`. The integrated inventory also includes concurrent relay containment scenarios; their fresh measurements are identified separately. No real scenarios executed. No scenario files changed. Phase 0 owns [HARNESS-CLASSIFICATION.md](HARNESS-CLASSIFICATION.md) and the evidence implementation field; this report does not duplicate or modify either. The per-scenario in-process column below is derived independently from scenario dispatch paths. No live gateway accessed. Measurements use prebuilt lab-tagged Go product binaries; Go prebuilding and transport are excluded; native fixture compilation inside the timed window is included.', '', f"{len(entries)} distinct IDs across {len(list(Path('lab/scenarios').rglob('*.yaml')))} YAMLs; REM-CRUD has separate SIM and real/replica files. Memberships: " + ', '.join(f"{level}={sum(level in e['levels'] for e in entries)}" for level in ['sim', 'real', 'replica', 'agent']) + '.', '', '## Measurement runs', '', 'Reference serial wall time: approximately 63 minutes, supplied in the task; not remeasured here. A partial or failing run cannot establish equivalent full-suite speedup.']
    if args.combined:
        combined = json.loads(Path(args.combined).read_text())
        unique = {row['id']: row for run in combined['runs'] for row in run['results']}
        outcomes = Counter(row['status'] for row in unique.values())
        lines.append(f"Integrated full SIM wall time: {combined['wall_seconds']:.3f}s for {len(unique)} scenarios ({sum(len(run['results']) for run in combined['runs'])} attempts, including prerequisite reruns); verdicts={dict(outcomes)}. Product revision: `{combined.get('product_revision', combined['source_revision'])}`. Timer spans launch through both hosts finishing, includes Air queueing, and excludes Go prebuilding/copying; native fixture compilation remains included. This is an attempted-suite timing with failures, not a passing-equivalence speedup claim.")
    lines.append('')
    for source, run in runs:
        lines.append(f"- {source}: host={run['host']}, workers={run['parallel']}, wall={run['wall_seconds']:.3f}s, complete={run['complete']}, results={dict(Counter(r['status'] for r in run['results']))}.")
    lines.append('')
    if len(runs) >= 2:
        first = {r['id']: r['status'] for r in runs[0][1]['results']}
        sample = runs[1][1]['results']
        matched = sum(first.get(r['id']) == r['status'] for r in sample)
        lines.append(f'Serial sample equivalence: {matched}/{len(sample)} verdicts match the parallel run (including baseline failures).')
    failures = sorted(identity for identity, row in measurements.items() if row['status'] != 'pass')
    lines += ['', 'Remaining SIM failures: ' + ', '.join(failures) + '.', '', 'The feature graph gate uses restored committed evidence for unowned scenarios, as WORKER-RULES requires; fresh regression verdicts remain in this inventory and measurements.json. New relay-containment evidence was generated by the integrated SIM run and used locally for that gate, without committing evidence owned by the relay worker.']
    lines += ['', '## Classification proposal', '', ', '.join(f'{name}: {counts[name]}' for name in ['keep', 'convert', 'merge', 'remove', 'run-at-end']) + '.', '', 'All classifications require owner approval. P-class and package maps are conservative static candidates, not measured coverage. Timing names identify contention-sensitive end gates, not demonstrated flakiness. No feature currently declares dropped status. CORE-ITERATOR-POOL is a removal proposal because its web.1 endpoint is absent from internal/web; removal is not inferred merely from a web-prefixed ID. Merge candidates need assertion comparison. See testing/README.md for inference limitations and test-selection.json for paths, roots, package and crate selectors.', '', '## Proposed real smoke set', '', ', '.join(smoke) + '.', '', 'This is a milestone proposal only. Effectful commands require the owner’s normal real-run authorization and fixture cleanup. Voicemail and Voice Memos have no declared real-level scenarios in this baseline; propose dedicated fixture-safe real journeys before claiming those sources covered. Any other unrepresented source needs its own declared real acceptance; SIM-only sources cannot qualify a real smoke set. Run TCC readiness first, then each source serially, then risky message commands. This task authorizes none of these executions.', '', '## Per-source real sets for the Swift shrink', '']
    focused = {
        'usage': ['USE-IMPORT', 'USE-LOCK-CLIP', 'USE-READONLY', 'USE-REMOTE-LAG'],
        'safari': ['SAF-HISTORY-REAL', 'SAF-BOOKMARKS-REAL'],
        'calls': ['CALL-READ-REAL'],
        'mail': ['MAIL-READ-REAL', 'MAIL-BODY-REAL', 'MAIL-DRAFT-REAL', 'MAIL-ORGANIZE-REAL'],
        'notes': ['NOTE-CRUD', 'NOTE-LIST', 'NOTE-EXTERNAL', 'NOTE-EDIT-PARITY', 'NOTE-RICH-REJECT'],
        'messages': ['MSG-INCOMING', 'MSG-HISTORY-IMPORT', 'MSG-READSTATE-REAL', 'MSG-COMMAND-OBSERVED-IDS', 'MSG-DELETE-REAL'],
        'calendar': ['CAL-CRUD', 'CAL-ALLDAY', 'CAL-RECUR-FUTURE', 'CAL-RECUR-THIS', 'CAL-MOVED-OCCURRENCE', 'CAL-MOVED-OUTSIDE-WINDOW', 'CAL-READONLY'],
        'contacts': ['CON-CRUD', 'CON-EXTERNAL', 'CON-HANDLE-LINK', 'CON-IMPORT', 'CON-NOTE', 'CON-ME'],
        'reminders': ['REM-CRUD', 'REM-LIST-MANAGE', 'REM-LIST-CREATE', 'REM-LIST-LOST-ACK', 'REM-RECURRING', 'REM-SECTIONS', 'REM-PERMISSION-LOSS'],
    }
    real_ids = {e['id'] for e in entries if 'real' in e['levels']}
    for source, candidates in focused.items():
        lines.append('- Focused ' + source + ': ' + ', '.join(identity for identity in candidates if identity in real_ids))
    lines += ['', 'Run HELPER-TCC-READY first for each source gate. Keep idle/performance observations at the milestone end. Every source cutover also requires the planned 24-hour zero-difference shadow; none is authorized or executed by this task.', '', 'Full declared real catalog by feature family:', '']
    lines += ['- voicemail: no declared real-level journey; propose a read-only VM-REAL capture/blob/absence-safety gate before migration.', '- voice-memos: no declared real-level journey; propose a read-only VMEMO-REAL inventory/blob gate before migration.']
    for source, ids in sorted(real_sets.items()):
        lines.append(f"- {source}: " + ', '.join(sorted(ids)))
    lines += ['', 'Swift shrink order: usage → safari → phone/recordings → mail → notes → messages → calendar/contacts. Add HELPER-TCC-READY, source restart/permission-loss and no-false-delete journeys to every relevant milestone. Source sets below are grouped by feature ownership; cross-source core/relay journeys remain final integration gates.', '', '## Slowest measured scenarios', '', '| Scenario | Seconds | Verdict |', '|---|---:|---|']
    for row in sorted(measurements.values(), key=lambda r: r['seconds'], reverse=True)[:10]:
        lines.append(f"| {row['id']} | {row['seconds']:.3f} | {row['status']} |")
    lines += ['', '## Per-scenario inventory', '', 'SIM seconds are end-to-end process wall time, including harness telemetry and cleanup. Each integrated scenario has one measured invocation (n=1); no repeat-run tail estimate is claimed. Air queue acquisition is excluded from scenario durations but included in combined wall time. A failed setup duration is not passing behavioral coverage. Historical real duration is unknown unless the evidence explicitly records whole-scenario start/end or duration; operation latencies and adjacent evidence timestamps are not substituted. Existing real evidence verdicts are retained separately. Historical run logs under lab/evidence were searched; they provide no reliably paired whole-scenario start/end timestamps. Raw logs are excluded from git.', '', '| Scenario | Levels | SIM seconds/verdict | Last real seconds/verdict | Go packages (inferred) | Swift modules (declared) | P candidate | Proposal and reason |', '|---|---|---|---|---|---|---|---|']
    for entry in entries:
        identity = entry['id']
        m = measurements.get(identity)
        sim = f"{m['seconds']:.3f}/{m['status']}" if m else ('unmeasured' if 'sim' in entry['levels'] else '—')
        real = '—'
        evidence_path = Path('lab/evidence/real') / (identity + '.json')
        if 'real' in entry['levels'] or evidence_path.exists():
            real = 'unknown/unverified'
            if evidence_path.exists():
                evidence = json.loads(evidence_path.read_text())
                seconds = evidence.get('scenario_duration_ms')
                duration = f'{seconds / 1000:.3f}' if isinstance(seconds, (float, int)) else 'unknown'
                verdict = evidence.get('status') or ('pass' if evidence.get('passed') is True else 'fail' if evidence.get('passed') is False else 'unverified')
                real = f"{duration}/{verdict} ({evidence.get('at', 'undated')[:10]})"
        lines.append('| ' + ' | '.join([identity, ', '.join(entry['levels']), sim, real, ', '.join(entry['packages']) or 'unresolved', ', '.join(entry['swift']) or '—', 'yes' if entry['p_class'] else 'unresolved', entry['recommendation'] + ': ' + entry['reason']]) + ' |')
    lines += ['', '## Air SIM candidates (native fixtures or missing Linux tooling)', '', ', '.join(e['id'] for e in entries if 'sim' in e['levels'] and e['host'] == 'darwin') + '.', '', 'Host routing is an audited starting list, updated when a Linux run reveals a native dependency. A failure due to missing xcrun, hdiutil, Swift modules, sibling iPhone checkout or legacy binary is a prerequisite failure, not a product regression. Full-suite verdict equivalence is not established while such failures or timeouts remain.']
    Path('lab/TEST-INVENTORY.md').write_text('\n'.join(lines) + '\n')


if __name__ == '__main__':
    main()
